    return Container(
      width: size.width * 0.8,
      height: size.width * 0.4,
      decoration: BoxDecoration(
        color: Color(0xFFFFF3E0),
        borderRadius: BorderRadius.circular(20),
        boxShadow: [
          BoxShadow(
            color: Colors.amber.withOpacity(0.2),
            spreadRadius: 5,
            blurRadius: 10,
            offset: const Offset(0, 3),
          ),
        ],
      ),
      child: Row(
        mainAxisAlignment: MainAxisAlignment.spaceEvenly,
        children: [
          // Position 24 (White pieces - start)
          _pieceStack(3, '24', size.width * 0.12, const Color(0xFFFFF3E0)),
          // Position 13 (5 black pieces)
          _pieceStack(5, '13', size.width * 0.12, const Color(0xFF2C1810)),
          // Position 8 (3 white pieces)
          _pieceStack(3, '8', size.width * 0.12, const Color(0xFFFFF3E0)),
          // Position 6 (5 black pieces)
          _pieceStack(5, '6', size.width * 0.12, const Color(0xFF2C1810)),
          // Position 1 (5 white pieces - bearing off)
          _pieceStack(5, '1', size.width * 0.12, const Color(0xFFFFF3E0)),
        ],
      ),
    );
  }

  /// Build a stack of pieces
  Widget _pieceStack(int count, String position, double size, Color background) {
    return Stack(
      clipBehavior: Clip.none,
      children: List.generate(
        count,
        (index) => Positioned(
          top: 8 - (index * 1.5),
          child: Container(
            width: size,
            height: size,
            decoration: BoxDecoration(
              color: background,
              shape: BoxShape.circle,
              boxShadow: [
                BoxShadow(
                  color: Colors.black26,
                  blurRadius: 3,
                  offset: const Offset(0, 1),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}